package org.jsoup.helper;

import org.jsoup.nodes.Document;
import org.jsoup.Connection;
import org.junit.Test;

import javax.net.ssl.SSLSocketFactory;
import java.io.IOException;
import java.io.InputStream;
import java.net.CookieStore;
import java.net.MalformedURLException;
import java.net.Proxy;
import java.net.URL;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;

public class HttpConnectionTest {

    @Test
    public void connectStringTest() throws MalformedURLException {
        HttpConnection connection = (HttpConnection) HttpConnection.connect("http://example.com");
        assertEquals(new URL("http://example.com"), connection.request().url());
    }

    @Test
    public void connectURLTest() throws MalformedURLException {
        URL url = new URL("http://example.com");
        HttpConnection connection = (HttpConnection) HttpConnection.connect(url);
        assertEquals(url, connection.request().url());
    }

    @Test
    public void urlTest() throws MalformedURLException {
        URL url = new URL("http://example2.com");
        HttpConnection connection = new HttpConnection();
        Connection con = connection.url(url);
        assertEquals(url, ((HttpConnection) con).request().url());
    }

    @Test
    public void urlStringTest() {
        String urlStr = "http://example2.com";
        HttpConnection connection = new HttpConnection();
        Connection con = connection.url(urlStr);
        assertEquals(urlStr, ((HttpConnection) con).request().url().toString());
    }

    @Test
    public void proxyTest() {
        HttpConnection connection = new HttpConnection();
        Proxy proxy = Proxy.NO_PROXY;
        Connection con = connection.proxy(proxy);
        assertEquals(proxy, ((HttpConnection) con).request().proxy());
    }

    @Test
    public void proxyHostPortTest() {
        HttpConnection connection = new HttpConnection();
        Connection con = connection.proxy("localhost", 8000);
        Proxy expectedProxy = new Proxy(Proxy.Type.HTTP, new InetSocketAddress("localhost", 8000));
        assertEquals(expectedProxy, ((HttpConnection) con).request().proxy());
    }

    @Test
    public void userAgentTest() {
        HttpConnection connection = new HttpConnection();
        Connection con = connection.userAgent("Jsoup/1.14.1");
        assertEquals("Jsoup/1.14.1", ((HttpConnection) con).request().userAgent());
    }

    @Test
    public void timeoutTest() {
        HttpConnection connection = new HttpConnection();
        connection.timeout(5000);
        assertEquals(5000, connection.request().timeout());
    }

    @Test
    public void sslSocketFactoryTest() {
        HttpConnection connection = new HttpConnection();
        SSLSocketFactory sslSocketFactory = (SSLSocketFactory) SSLSocketFactory.getDefault();
        connection.sslSocketFactory(sslSocketFactory);
        assertEquals(sslSocketFactory, connection.request().sslSocketFactory());
    }

    @Test
    public void dataMapTest() {
        HttpConnection connection = new HttpConnection();
        Map<String, String> data = new HashMap<>();
        data.put("name", "John");
        data.put("age", "25");
        connection.data(data);
        assertEquals(data, connection.request().data());
    }

    @Test
    public void getTest() throws IOException {
        HttpConnection connection = (HttpConnection) HttpConnection.connect("http://example.com");
        Document document = connection.get();
        assertEquals("http://example.com", document.baseUri());
    }

    @Test
    public void postTest() throws IOException {
        HttpConnection connection = (HttpConnection) HttpConnection.connect("http://example.com");
        Document document = connection.post();
        assertEquals("http://example.com", document.baseUri());
    }

    @Test
    public void requestTest() {
        HttpConnection connection = new HttpConnection();
        Connection.Request request = mock(Connection.Request.class);
        connection.request(request);
        assertEquals(request, connection.request());
    }

    @Test
    public void responseTest() {
        HttpConnection connection = new HttpConnection();
        Connection.Response response = mock(Connection.Response.class);
        connection.response(response);
        assertEquals(response, connection.response());
    }

    @Test
    public void postDataCharsetTest() {
        HttpConnection connection = new HttpConnection();
        connection.postDataCharset("UTF-8");
        assertEquals("UTF-8", connection.request().postDataCharset());
    }
}
